class Solution {
    public void reorderList(ListNode head) {
        if (head == null || head.next == null) return;

        // Step 1: Find middle
        ListNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // Step 2: Reverse second half
        ListNode second = slow.next;
        slow.next = null;
        ListNode prev = null;
        while (second != null) {
            ListNode next = second.next;
            second.next = prev;
            prev = second;
            second = next;
        }
        second = prev;

        // Step 3: Merge two halves
        ListNode first = head;
        while (second != null) {
            ListNode tmp1 = first.next;
            ListNode tmp2 = second.next;
            first.next = second;
            second.next = tmp1;
            first = tmp1;
            second = tmp2;
        }
    }
}

import java.util.*;

class Solution {
    public void reorderList(ListNode head) {
        if (head == null) return;

        Deque<ListNode> deque = new ArrayDeque<>();
        ListNode curr = head.next;
        while (curr != null) {
            deque.addLast(curr);
            curr = curr.next;
        }

        curr = head;
        boolean fromBack = true;
        while (!deque.isEmpty()) {
            ListNode node = fromBack ? deque.pollLast() : deque.pollFirst();
            curr.next = node;
            curr = node;
            fromBack = !fromBack;
        }
        curr.next = null;
    }
}
